def group_and_sort_by_department(records):
    groups = {}

    for record in records:
        dept = record["department"]
        groups.setdefault(dept, []).append(record)

    def sort_key(item):
        score = item.get("score")
        missing = not isinstance(score, (int, float)) or isinstance(score, bool)
        return (missing, -(score if not missing else 0))

    for dept in groups:
        groups[dept] = sorted(groups[dept], key=sort_key)

    return groups


# Sample input
records = [
    {"name": "Alice", "department": "Sales", "score": 91},
    {"name": "Bob", "department": "Sales", "score": None},
    {"name": "Cara", "department": "Engineering", "score": 88},
    {"name": "Dan", "department": "Sales", "score": 97},
    {"name": "Eve", "department": "Engineering"},
]

result = group_and_sort_by_department(records)
print(result)

